import{z as o,x as p,o as E,c as A,q as B,j as l,D as r,d as s,s as i,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"ABR 自适应码率","description":"","frontmatter":{"title":"ABR 自适应码率","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/abr-streaming.md","filePath":"cs/abr-streaming.md","lastUpdated":1791063341000}'),d={name:"cs/abr-streaming.md"};function D(C,a,h,m,c,b){const t=p("Mermaid");return E(),A("div",null,[a[2]||(a[2]=B('<h1 id="abr-自适应码率" tabindex="-1">ABR 自适应码率 <a class="header-anchor" href="#abr-自适应码率" aria-label="Permalink to &quot;ABR 自适应码率&quot;">​</a></h1><div class="epigraph"><p>播放器根据吞吐估计与缓冲水位在阶梯码率间切换，逼近瞬时可用带宽，避免卡顿或无谓的 4K。</p><footer>—— 据 Huang et al. 缓冲基 ABR；DASH/HLS 实践；Kurose 多媒体节整理</footer></div><p><a href="/cs/dash-hls">DASH/HLS</a> 提供阶梯。<a href="/cs/mimo-rate-adaptation">速率自适应</a> 在 Wi‑Fi PHY。<a href="/cs/dash-hls">上一课</a> 留下选哪一档。缺口是 <strong>ABR 控制</strong>：吞吐估计、缓冲、振荡。本课不把 CDN 层次写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>可用带宽随 Wi‑Fi、蜂窝、同屋流变化。固定高码率则再缓冲；固定低则浪费 \\(C\\)。ABR：测最近分片吞吐，看缓冲秒数，选下一表示。过敏则码率振荡（视觉差），过钝则卡。与 TCP CC 叠：ABR 在应用，CUBIC 在运输，双环。BBR 下估计更稳或仍抖，取决于实现。</p><p>不要把 ABR 写成 5G 切片保证。</p><p><span class="marginnote">缓冲基（BBA）等算法。本课不点名商业播放器。</span></p><p><span class="marginnote">数字实例：阶梯码率常见如 240p 约 0.4 Mbps、720p 约 3 Mbps、1080p 约 6 Mbps。网络实际只有 4 Mbps 却锁 1080p，每秒就欠 2 Mbps，缓冲几十秒后耗尽必然卡顿；自动降到 720p 反而能一秒不断。</span></p><p><span class="marginnote">直觉类比：TCP 拥塞控制在运输层「探路有多宽」，ABR 在应用层「看路况决定开多快」——两个环叠着转。若 ABR 对吞吐的每次抖动都立刻反应，就会像新手司机一样忽快忽慢（码率振荡），所以估计必须滤波。</span></p><h3 id="应用层跟踪可用带宽" tabindex="-1">应用层跟踪可用带宽 <a class="header-anchor" href="#应用层跟踪可用带宽" aria-label="Permalink to &quot;应用层跟踪可用带宽&quot;">​</a></h3><p>与 TCP/BBR 双环，要滤波防振荡。令牌桶边缘限速会表现为「网慢」。清单缺中间档则跳变。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：基于吞吐 / 基于缓冲 / 混合。画：下片 → 估 BW → 选档。与令牌桶：边缘限速会让 ABR 降档，表现为「网很慢」。</p>',13)),(E(),l(n,null,{default:r(()=>[i(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20THR%5B%22%E5%88%86%E7%89%87%E5%90%9E%E5%90%90%22%5D%20--%3E%20DEC%5B%22%E9%80%89%E7%A0%81%E7%8E%87%22%5D%0A%20%20BUF%5B%22%E7%BC%93%E5%86%B2%E6%B0%B4%E4%BD%8D%22%5D%20--%3E%20DEC%0A%20%20DEC%20--%3E%20NEXT%5B%22%E4%B8%8B%E4%B8%80%E5%88%86%E7%89%87%20GET%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[s("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"CDN 不同 POP 吞吐不同，切换 POP 像路径变。ECN 膨胀影响估计。QUIC 迁移换路要重新估计。无线 TCP 误码让吞吐锯齿，ABR 应滤波。与 WFQ：隔离后估计更干净。",-1)),a[5]||(a[5]=e("p",null,"安全：恶意慢片可诱骗降档，点名。",-1)),a[6]||(a[6]=e("p",null,"第一张图画的是选档吃哪两路输入；这张图回答第二个问题：同样的输入下，缓冲水位落在哪个区间，决策就完全不同——这就是缓冲基算法的核心逻辑。",-1)),(E(),l(n,null,{default:r(()=>[i(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20BUF%5B%22%E5%BD%93%E5%89%8D%E7%BC%93%E5%86%B2%E7%A7%92%E6%95%B0%22%5D%20--%3E%20LOW%7B%22%E9%80%BC%E8%BF%91%E5%8D%B1%E9%99%A9%E7%BA%BF%EF%BC%9F%22%7D%0A%20%20LOW%20--%3E%7C%22%E6%98%AF%EF%BC%8C%E5%BF%AB%E6%B2%A1%E7%89%87%E4%BA%86%22%7C%20DOWN%5B%22%E9%99%8D%E6%A1%A3%EF%BC%9A%E5%85%88%E4%BF%9D%E4%B8%8D%E5%8D%A1%22%5D%0A%20%20LOW%20--%3E%7C%22%E5%90%A6%22%7C%20MID%7B%22%E6%B0%B4%E4%BD%8D%E5%85%85%E8%A3%95%EF%BC%9F%22%7D%0A%20%20MID%20--%3E%7C%22%E4%B8%80%E8%88%AC%22%7C%20HOLD%5B%22%E7%BB%B4%E6%8C%81%E5%BD%93%E5%89%8D%E6%A1%A3%22%5D%0A%20%20MID%20--%3E%7C%22%E6%98%AF%22%7C%20UP%5B%22%E5%8D%87%E6%A1%A3%EF%BC%9A%E8%AF%95%E6%9B%B4%E9%AB%98%E7%A0%81%E7%8E%87%22%5D%0A%20%20DOWN%20--%3E%20NEXT%5B%22%E8%AF%B7%E6%B1%82%E4%B8%8B%E4%B8%80%E5%88%86%E7%89%87%22%5D%0A%20%20HOLD%20--%3E%20NEXT%0A%20%20UP%20--%3E%20NEXT%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=B('<p><span class="marginnote">常见误区：初学者容易以为 ABR 的目标是「尽量播最高清」。实际目标是卡顿与画质的折中——一次三秒的转圈缓冲，比全程 720p 难受得多。若阶梯清单里缺了中间档位，控制算法再好也只能在 0.4 和 6 Mbps 之间大幅跳变。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入强化学习 ABR 的全部。CDN 缓存层次与失效是下一课。后课默认：ABR 是应用层对可用带宽的阶梯跟踪。</p><p>清单若缺中间档，控制再好也跳变。</p><p>下一课<a href="/cs/cdn-cache-hierarchy">CDN 缓存层次与失效</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>吞吐与缓冲驱动选档。</li><li>与 TCP/BBR 形成双环，要滤波。</li><li>目标是卡顿与质量折中，不是峰值码率。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：ABR 文献；DASH/HLS 实践。</li></ul>',7))])}const T=o(d,[["render",D]]);export{f as __pageData,T as default};
